from datetime import datetime, date, timedelta
from dateutil.relativedelta import relativedelta as rd

# Compare rd + rd with elementwise addition, and rd*2 with rd+rd
import itertools, random
random.seed(0)
fields = ['years','months','days','hours','minutes','seconds','microseconds']
bad=[]
for _ in range(2000):
    kw = {f: random.choice([0,1,2,3,-1,-2,0.5,1.5,2.5,-0.5]) for f in fields}
    try:
        a = rd(**kw)
    except ValueError:
        continue
    # rd + rd == rd * 2 (for relative fields)
    try:
        s = a + a
        m = a * 2
        if s != m:
            bad.append((kw, 'a+a != a*2', repr(s), repr(m)))
    except Exception as e:
        bad.append((kw, 'exc', repr(e)))
    # normalized should be equivalent when added to a datetime
    try:
        d = datetime(2000,1,1)
        r1 = d + a
        r2 = d + a.normalized()
        if r1 != r2:
            bad.append((kw, 'normalized differs', r1, r2))
    except Exception as e:
        bad.append((kw, 'norm exc', repr(e)))
print("bad count", len(bad))
